ax1.text(2.1, 1, 'Altura maxima (t=2s, v=0)', fontsize=10)

ax1.plot(3, -10, 'ko', markersize=6)
ax1.text(3.1, -9, 'Descenso (t=3s, v=-10 m/s)', fontsize=10)

